--
-- Table structure for table `service_agents`
--

DROP TABLE IF EXISTS `service_agents`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `service_agents` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `authorized_user_id` bigint NOT NULL,
  `agent_code` varchar(50) DEFAULT NULL,
  `agent_type` varchar(50) DEFAULT NULL,
  `full_name` varchar(200) DEFAULT NULL,
  `email` varchar(200) DEFAULT NULL,
  `mobile` varchar(50) DEFAULT NULL,
  `assigned_region` varchar(100) DEFAULT NULL,
  `assigned_segment` varchar(100) DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT '1',
  `onboarding_status` varchar(50) DEFAULT NULL,
  `tenant_id` bigint NOT NULL,
  `created_by` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `modified_by` varchar(255) DEFAULT NULL,
  `modified_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `address_proof_url` varchar(500) DEFAULT NULL,
  `deleted_at` datetime(6) DEFAULT NULL,
  `dv_service_agent_id` varchar(100) DEFAULT NULL,
  `onboarded_at` datetime(6) DEFAULT NULL,
  `onboarded_by` varchar(200) DEFAULT NULL,
  `pan_number` varchar(20) DEFAULT NULL,
  `photo_url` varchar(500) DEFAULT NULL,
  `registration_number` varchar(100) DEFAULT NULL,
  `service_provider_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `agent_code` (`agent_code`),
